import json,numpy as np
m=json.load(open('/app/output/close_ball/meta.json'))
tcp=np.array(m['proprio']['now'][:3]); ball=np.array([.03,.70,.05]);
print('tcp',tcp)
for c in ['front','left','right','topview']:
 T=np.array(m['cameras'][c]['cam2world_gl']); K=np.array(m['cameras'][c]['intrinsic_cv']);
 for name,p in [('tcp',tcp),('ball',ball)]:
  gl=np.linalg.inv(T[:3,:3])@(p-T[:3,3]); d=-gl[2]; u=K[0,0]*gl[0]/d+K[0,2]; v=K[1,2]-K[1,1]*gl[1]/d
  print(c,name,(u,v),'depth',d)
